import { ChartUnit } from '../../../../core/types/chart-unit.js';
import { Formatter } from '../../../../core/types/formatter.js';
import { TooltipItem } from '../../../../core/types/tooltip.js';
import { safeGet } from '../../../providers/HistogramDataProvider.js';
import { WeakMapBins } from '../../../types/histogram.js';
import { HistogramDataPoint } from '../HistogramExplore/HistogramExploreOverlay.js';

/**
 * generate the tooltip items from the ponts and closes point
 *
 * return -
 */

export function toTooltipItems(
  binsMap: WeakMapBins,
  formatters: Formatter[],
  isSingle: boolean,
  units: ChartUnit[],
  points?: HistogramDataPoint[],
  closesPoint?: HistogramDataPoint,
): { tooltipItems: TooltipItem[]; closestTooltipItem?: TooltipItem } {
  if (!closesPoint) {
    return { tooltipItems: [], closestTooltipItem: undefined };
  }

  const binMetadata = safeGet(binsMap, closesPoint.bin);

  const [leftUnit] = units;
  const [leftFormatter, rightFormatter] = formatters;
  const formatter =
    binMetadata.unit === leftUnit ? leftFormatter : rightFormatter;

  const closestTooltipItem = {
    id: binMetadata.seriesId,
    name: binMetadata.seriesName,
    color: binMetadata.color,
    values: [formatter(binMetadata.value, binMetadata.unit)],
  };

  if (!isSingle) {
    const tooltipItems = points
      ? points.map((point) => {
          const binMetadata = safeGet(binsMap, point.bin);

          return {
            id: binMetadata.seriesId,
            name: binMetadata.seriesName,
            color: binMetadata.color,
            values: [formatter(binMetadata.value, binMetadata.unit)],
          };
        })
      : [];

    return { tooltipItems, closestTooltipItem };
  }

  return {
    tooltipItems: [closestTooltipItem],
    closestTooltipItem,
  };
}
